export const takeSummary=take=>({id:take.id,name:take.name,created:take.created,frames:take.frames,sampleRate:take.sampleRate,seamMs:take.seamMs,events:take.events.length,bytes:take.channels[0].byteLength*2});
export class PerformanceStore{
 async open(){if(this.db)return this.db;if(!globalThis.indexedDB)throw new Error('Browser storage is unavailable. You can still record and download a take.');if(!this.pending)this.pending=new Promise((resolve,reject)=>{const request=indexedDB.open('chromaflow-performances',1);request.onupgradeneeded=()=>{request.result.createObjectStore('takes',{keyPath:'id'});request.result.createObjectStore('index',{keyPath:'id'});};request.onsuccess=()=>{this.db=request.result;this.db.onversionchange=()=>{this.db.close();this.db=null;this.pending=null;};resolve(this.db);};request.onerror=()=>{this.pending=null;reject(new Error('The browser could not open the performance library.'));};request.onblocked=()=>{this.pending=null;reject(new Error('Close other Chromaflow tabs and try the library again.'));};});return this.pending;}
 async transaction(mode,names,action){const db=await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction(names,mode);let result;const request=action(tx);if(request)request.onsuccess=()=>{result=request.result;};tx.oncomplete=()=>resolve(result);tx.onabort=tx.onerror=()=>reject(new Error('The browser could not save this change. Storage may be full; download your take to keep it.'));});}
 async list(){const takes=await this.transaction('readonly',['index'],tx=>tx.objectStore('index').getAll());return takes.sort((a,b)=>b.created.localeCompare(a.created));}
 get(id){return this.transaction('readonly',['takes'],tx=>tx.objectStore('takes').get(id));}
 put(take){return this.transaction('readwrite',['takes','index'],tx=>{tx.objectStore('takes').put(take);return tx.objectStore('index').put(takeSummary(take));});}
 remove(id){return this.transaction('readwrite',['takes','index'],tx=>{tx.objectStore('takes').delete(id);return tx.objectStore('index').delete(id);});}
}
